def detect_anomaly(steps, max_steps=10):
    issues = []
    if len(steps) > max_steps:
        issues.append("超出步数")
    run_tool, run_len = None, 0
    for s in steps:
        t = s.get("tool")
        if t == run_tool:
            run_len += 1
        else:
            run_tool, run_len = t, 1
        if run_len >= 3 and "重复调用" not in issues and t:
            issues.append("重复调用")
        if s.get("error"):
            if "工具报错" not in issues:
                issues.append("工具报错")
    return issues


